function isDesktop() {
return window.innerWidth > 768;
}
function getCartIconRect() {
var vw = window.innerWidth || document.documentElement.clientWidth;
var vh = window.innerHeight || document.documentElement.clientHeight;
var $ct = $('.cxb-b2b-quote-basket-toggle');
if ($ct.length && $ct.is(':visible') && !$ct.hasClass('hidden')) {
var r = $ct[0].getBoundingClientRect();
if (r.width > 0 && r.height > 0) return r;
}
var pos = CFG.quote_cart_position || 'bottom-right';
var bot = parseInt(CFG.quote_cart_bottom_spacing, 10) || 20;
var cw = 60, ch = 60, cx = 30;
var top = vh - bot - ch;
var left = (pos === 'bottom-left') ? cx : vw - cx - cw;
return { top: top, bottom: top + ch, left: left, right: left + cw, width: cw, height: ch };
}
function positionToastContainer($tc) {
requestAnimationFrame(function() {
var vw = window.innerWidth || document.documentElement.clientWidth;
var vh = window.innerHeight || document.documentElement.clientHeight;
var cr = getCartIconRect();
var toastBottom = (vh - cr.top) + 14;
var cw = 300;
if ($tc.children().length > 0) cw = Math.min($tc.outerWidth() || 300, 300);
var idealLeft = cr.left + (cr.width / 2) - (cw / 2);
var margin = 20;
if (idealLeft < margin) idealLeft = margin;
else if (idealLeft + cw > vw - margin) idealLeft = vw - cw - margin;
$tc.css({
position: 'fixed', bottom: toastBottom + 'px', left: idealLeft + 'px',
top: 'auto', right: 'auto', maxWidth: '300px', width: 'auto'
});
var arrowX = cr.left + (cr.width / 2) - idealLeft;
arrowX = Math.max(16, Math.min(arrowX, cw - 16));
$tc[0].style.setProperty('--cxb-toast-arrow-x', Math.round(arrowX) + 'px');
});
}
function showToastNotification(message, isSuccess) {
if (!isDesktop()) return;
var $tc = $('.cxb-b2b-toast-container');
if (!$tc.length) {
$('body').append('<div class="cxb-b2b-toast-container"></div>');
$tc = $('.cxb-b2b-toast-container');
}
var cls = isSuccess ? 'cxb-b2b-toast-success' : 'cxb-b2b-toast-error';
var extra = isSuccess ? '' : 'error';
var icon = isSuccess
? '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="20 6 9 17 4 12"></polyline></svg>'
: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg>';
var $toast = $('<div class="cxb-b2b-toast ' + cls + ' ' + extra + '"></div>')
.append('<div class="cxb-b2b-toast-icon">' + icon + '</div>')
.append('<div class="cxb-b2b-toast-message">' + message + '</div>');
$tc.attr({ role: 'status', 'aria-live': 'polite' });
$tc.append($toast);
positionToastContainer($tc);
$tc.addClass('visible');
var onResize = function() { positionToastContainer($tc); };
$(window).on('resize', onResize);
setTimeout(function() { $toast.addClass('show'); }, 10);
setTimeout(function() { positionToastContainer($tc); }, 320);
setTimeout(function() {
$toast.removeClass('show').addClass('hiding');
setTimeout(function() {
$toast.remove();
$(window).off('resize', onResize);
if ($tc.children().length === 0) $tc.removeClass('visible');
}, 300);
}, 3000);
}
function showQuoteFeedback($button, isSuccess, customMessage) {
var msg = customMessage || (isSuccess ? t('product_added', 'Product added to quote list') : t('product_already_added', 'Product already in quote list'));
if (isSuccess) {
var shownToast = false;
try { shownToast = sessionStorage.getItem('cxb_b2b_toast_shown'); } catch(e) {}
if (!shownToast && isDesktop()) {
showToastNotification(msg, true);
try { sessionStorage.setItem('cxb_b2b_toast_shown', 'true'); } catch(e) {}
}
} else {
if (isDesktop()) showToastNotification(msg, false);
}
$button.addClass(isSuccess ? 'success-temp' : 'error-temp');
setTimeout(function() { $button.removeClass('success-temp error-temp'); }, 2000);
if (isSuccess && isDesktop()) {
var shownVibrate = false;
try { shownVibrate = sessionStorage.getItem('cxb_b2b_vibrate_shown'); } catch(e) {}
if (!shownVibrate) {
var $ct = $('.cxb-b2b-quote-basket-toggle:not(.hidden)');
if ($ct.length && $ct.is(':visible')) {
$ct.addClass('vibrate-ripple');
try { sessionStorage.setItem('cxb_b2b_vibrate_shown', 'true'); } catch(e) {}
setTimeout(function() { $ct.removeClass('vibrate-ripple'); }, 3000);
}
}
}
}
